113	     * re-sending diseases that were just received from the mate.
114	     * @param mate The male mate that the female breeds with.
115	     */
116	    protected void giveDiseases(Animal mate)
117	    {
118	        Set<Disease> ownDiseasesSnapshot = new HashSet<>(setDiseases);
119	        for (Disease disease: mate.setDiseases){
120	            if (disease.isSpreadByBirth()){
121	                setDiseases.add(disease);
122	            }
123	        }
124	        for (Disease disease: ownDiseasesSnapshot){
125	            if (disease.isSpreadByBirth()){
126	                mate.getActorDiseaseSet().add(disease);
127	            }
128	        }
129	    }
