132	     * Look for prey adjacent to the current location.
133	     * Only the first live prey is eaten.
134	     * @return Where food was found, or null if it wasn't.
135	     */
136	    protected Location findFood()
137	    {
138	        Field field = getField();
139	        for(Location where : field.adjacentLocations(getLocation())) {
140	            if ((canMoveOnLand() && canMoveOnWater()) || (field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnWater()) || (!field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnLand())) {
141	                Object actor = field.getObjectAt(where);
142	                if (actor instanceof Actor) {
143	                    Actor prey = (Actor) actor;
144	                    Integer foodValue = getPreyFoodValuesMap().get(prey.getClass());
145	                    if(foodValue != null && prey.isAlive()) {
146	                        for (Disease disease: prey.setDiseases){
147	                            if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getClass())){
148	                                setDiseases.add(disease);
149	                            }
150	                        }
151	                        prey.setDead();
152	                        foodLevel = Math.min(foodLevel + foodValue, getMaxFood());
